BEGIN;
SELECT set_config('request.jwt.claim.role','service_role',true);
SELECT set_config('festapp.email_wake','scheduled',true);
DO $$
DECLARE org bigint; un bigint; oc bigint; f bigint; fk uuid; pt bigint; product bigint; acc bigint; oid bigint; waitoid bigint; actor uuid;
 input jsonb; result jsonb; proposal jsonb; send_payload jsonb; offer uuid; token text:=repeat('a',64); person uuid; command uuid; client uuid:=gen_random_uuid(); delivery jsonb;
BEGIN
 INSERT INTO organizations(title) VALUES('Waitlist smoke') RETURNING id INTO org;
 INSERT INTO units(title,organization) VALUES('Waitlist smoke',org) RETURNING id INTO un;
 INSERT INTO occasions(title,unit,organization,link,start_time,end_time) VALUES('Waitlist smoke',un,org,'waitlist-smoke',now(),now()+interval '1 day') RETURNING id INTO oc;
 INSERT INTO forms(occasion,link,participant_capacity,waitlist_enabled,waitlist_offer_duration_seconds) VALUES(oc,'waitlist-smoke',1,true,3600) RETURNING id,key INTO f,fk;
 INSERT INTO eshop.bank_accounts(title,type,supported_currencies) VALUES('Waitlist bank','FIO',ARRAY['CZK']) RETURNING id INTO acc;
 INSERT INTO eshop.unit_bank_accounts(unit,bank_account) VALUES(un,acc);
 INSERT INTO eshop.product_types(title,type,occasion) VALUES('spot','spot',oc) RETURNING id INTO pt;
 INSERT INTO eshop.products(title,product_type,price,currency_code,occasion) VALUES('Admission',pt,100,'CZK',oc) RETURNING id INTO product;
 INSERT INTO form_fields(form,product_type,type) VALUES(f,pt,'product_type');
 SELECT id INTO actor FROM auth.users LIMIT 1;
 INSERT INTO occasion_users(occasion,"user",is_editor_order,is_editor_order_view) VALUES(oc,actor,true,true);
 input:=jsonb_build_object('form',fk,'email','smoke@example.invalid','ticket',jsonb_build_array(jsonb_build_object('fields',jsonb_build_array(jsonb_build_object('product_type',product)))));
 result:=public.create_ticket_order_internal_v1(input);
 IF result->>'code'<>'200' THEN RAISE EXCEPTION 'Regular failed %',result; END IF;
 oid:=(result#>>'{order,id}')::bigint;
 IF (public.get_form_capacity_snapshot_internal(f)->>'occupiedPeople')::int<>1 THEN RAISE EXCEPTION 'Regular participants missing'; END IF;
 delivery:=jsonb_build_object('recipient','wait@example.invalid','templateCode','waitlist_confirmation','tokenHash',encode(extensions.digest(token,'sha256'),'hex'),'contentHash',repeat('f',64),'sealed',jsonb_build_object('ciphertext','mocked'));
 result:=public.execute_waitlist_command_client_sync_v1('register',jsonb_build_object('form',fk,'email','wait@example.invalid','people',jsonb_build_array(jsonb_build_object('fields','[]'::jsonb),jsonb_build_object('fields','[]'::jsonb))),gen_random_uuid(),client,NULL,jsonb_build_array(delivery));
 IF result#>>'{data,code}'<>'200' THEN RAISE EXCEPTION 'Register failed %',result; END IF;
 waitoid:=(result#>>'{data,order,id}')::bigint;
 PERFORM public.update_order_and_tickets_to_storno_221(oid);
 PERFORM set_config('request.jwt.claim.sub',actor::text,true);
 proposal:=public.get_waitlist_offer_proposal(f);
 send_payload:=jsonb_build_object('formId',f,'revision',proposal->'revision','expiresAt',now()+interval '1 hour','recipients',jsonb_build_array(jsonb_build_object('orderId',waitoid,'count',1)));
 delivery:=jsonb_build_object('orderId',waitoid,'recipient','wait@example.invalid','templateCode','waitlist_offer','tokenHash',encode(extensions.digest(repeat('b',64),'sha256'),'hex'),'contentHash',repeat('e',64),'sealed',jsonb_build_object('ciphertext','mocked'));
 result:=public.execute_waitlist_command_client_sync_v1('send',send_payload,gen_random_uuid(),client,actor,jsonb_build_array(delivery));
 IF result#>>'{data,code}'<>'200' THEN RAISE EXCEPTION 'Send failed %',result; END IF;
 offer:=(result#>>'{data,offers,0,offerId}')::uuid;
 SELECT id INTO person FROM eshop.order_participants WHERE current_order_id=waitoid ORDER BY id LIMIT 1;
 input:=jsonb_build_object('form',fk,'email','wait@example.invalid','ticket',jsonb_build_array(jsonb_build_object('participantId',person,'fields',jsonb_build_array(jsonb_build_object('product_type',product)))));
 INSERT INTO eshop.external_services(unit,type,data) VALUES(un,'FAKTUROID','{}');
 command:=gen_random_uuid();
 result:=public.execute_waitlist_command_client_sync_v1('accept',jsonb_build_object('offerId',offer,'personIds',jsonb_build_array(person),'orderDetails',input),command,client,actor);
 IF result#>>'{data,code}'<>'200' THEN RAISE EXCEPTION 'Accept failed %',result; END IF;
 IF result#>>'{data,conversion}'<>'split' THEN RAISE EXCEPTION 'Wrong conversion %',result; END IF;
 PERFORM set_config('request.jwt.claim.sub','',true);
 PERFORM public.abort_fakturoid_ticket_order_v1((result#>>'{data,order,id}')::bigint,command);
 PERFORM public.abort_fakturoid_ticket_order_v1((result#>>'{data,order,id}')::bigint,command);
 IF (SELECT count(*) FROM eshop.order_participants WHERE current_order_id=waitoid)<>2 THEN RAISE EXCEPTION 'Abort failed persons restore'; END IF;
 IF (SELECT count(*) FROM eshop.waitlist_offer_slots WHERE offer_id=offer AND outcome='pending')<>1 THEN RAISE EXCEPTION 'Abort failed slot restore'; END IF;
 IF (SELECT state FROM eshop.orders WHERE id=waitoid)<>'waitlisted' THEN RAISE EXCEPTION 'Abort failed source state restore'; END IF;
 result:=public.execute_waitlist_command_client_sync_v1('accept',jsonb_build_object('offerId',offer,'personIds',jsonb_build_array(person),'orderDetails',input),gen_random_uuid(),client,actor);
 IF result#>>'{data,code}'<>'200' THEN RAISE EXCEPTION 'Retry failed %',result; END IF;

 IF (public.get_form_capacity_snapshot_internal(f)->>'occupiedPeople')::int<>1 OR (public.get_form_capacity_snapshot_internal(f)->>'offeredPlaces')::int<>0 THEN RAISE EXCEPTION 'Capacity mismatch'; END IF;
 RAISE NOTICE 'PASS regular/register/send/split acceptance';
END $$;
ROLLBACK;
